package cn.mop.api;
import cn.mop.domain.*;
import cn.mop.domain.monitoring.ThresholdConditionAnalysis.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import org.junit.jupiter.api.*;
import org.springframework.mock.web.MockHttpServletRequest;
import java.nio.charset.StandardCharsets;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
class ThresholdDiagnosticControllerTest {
    static final String ACTOR="67000000-0000-4000-8000-000000000001",TENANT="67000000-0000-4000-8000-000000000002";
    PlatformRepository platform;ThresholdDiagnosticController controller;ObjectMapper mapper=new ObjectMapper();
    @BeforeEach void setup(){platform=mock(PlatformRepository.class);controller=new ThresholdDiagnosticController(platform);member("padmin",true,1);}
    void member(String role,boolean active,long version){when(platform.membership(ACTOR,TENANT)).thenReturn(Optional.of(new Membership(ACTOR,TENANT,role,version,active)));}
    ObjectNode condition(String op,String value){return mapper.createObjectNode().put("comparison",op).put("threshold",value).put("unit","EXPLICIT_UNIT");}
    ObjectNode input(){var v=mapper.createObjectNode().put("direction","HIGH_IS_BAD").put("trigger_hold_seconds","300").put("recovery_hold_seconds","60");v.set("warning",condition("GT","70"));v.set("critical",condition("GT","85"));v.set("recovery",condition("LT","65"));return v;}
    MockHttpServletRequest request(String body){var r=new MockHttpServletRequest("POST","/api/v1/monitoring/threshold-diagnostics");r.setUserPrincipal(()->ACTOR);r.getSession().setAttribute("mop.tenant_id",TENANT);r.setContentType("application/json");r.setContent(body.getBytes(StandardCharsets.UTF_8));return r;}
    Map<?,?> data(String raw){return (Map<?,?>)((Map<?,?>)controller.analyze(request(raw))).get("data");}
    @Test void consistentMathematicsNeverPublishesOrReadsRuleRegistry(){var d=data(input().toString());assertEquals(Status.CONSISTENT,d.get("status"));assertEquals(TENANT,d.get("tenant_id"));for(String k:List.of("publishable","units_converted","monitoring_applied","time_series_evaluated","rule_saved","writes_performed"))assertEquals(false,d.get(k));assertNull(d.get("effective_rule"));assertEquals("NOT_RUN",d.get("physical_range_check"));assertEquals("UNVERIFIED",d.get("customer_confirmation"));verify(platform).membership(ACTOR,TENANT);verifyNoMoreInteractions(platform);}
    @Test void unknownInputsReturnUnresolvedAndAllMissingFieldsStayNull(){var v=input();for(String key:new ArrayList<String>(){{v.fieldNames().forEachRemaining(this::add);}})v.putNull(key);var d=data(v.toString());assertEquals(Status.UNRESOLVED,d.get("status"));assertNull(d.get("direction_consistent"));assertNull(d.get("durations_nonnegative"));assertEquals(6,((List<?>)d.get("issues")).size());assertTrue(((Map<?,?>)d.get("inputs")).values().stream().allMatch(Objects::isNull));}
    @Test void reversedRecoveryRemainsOriginalOperatorWithConflictNotCorrection(){var v=input();v.set("recovery",condition("GT","15"));var d=data(v.toString());assertEquals(Status.CONFLICT,d.get("status"));assertEquals(true,d.get("recovery_overlaps_warning"));assertEquals(Comparison.GT,((Map<?,?>)((Map<?,?>)d.get("inputs")).get("recovery")).get("comparison"));}
    @Test void decimalStringsRetainPrecisionAndScaleRatherThanRoundingToBinary(){var v=input();v.set("warning",condition("GT","0.99999999999999999"));v.set("critical",condition("GT","1.000"));v.set("recovery",condition("LT","0.5"));var d=data(v.toString());assertEquals(Status.CONSISTENT,d.get("status"));assertEquals("1.000",((Map<?,?>)((Map<?,?>)d.get("inputs")).get("critical")).get("threshold"));}
    @Test void unitMismatchCannotYieldComparableCriticalResult(){var v=input();((ObjectNode)v.get("critical")).put("unit","OTHER");var d=data(v.toString());assertEquals(Status.CONFLICT,d.get("status"));assertNull(d.get("critical_strict_subset_of_warning"));assertNull(d.get("recovery_overlaps_critical"));}
    @Test void explicitNegativeDurationIsDiagnosticConflictNotGuessedZero(){var v=input().put("trigger_hold_seconds","-0.5");var d=data(v.toString());assertEquals(Status.CONFLICT,d.get("status"));assertEquals(false,d.get("durations_nonnegative"));assertEquals("-0.5",((Map<?,?>)d.get("inputs")).get("trigger_hold_seconds"));}
    @Test void onlyCurrentPlatformConfigurationAdministratorPermittedBeforeParsing(){for(String role:List.of("tadmin","msp","viewer","unknown")){member(role,true,1);assertEquals(403,assertThrows(DomainException.class,()->data("broken")).status);}verify(platform,times(4)).membership(ACTOR,TENANT);verifyNoMoreInteractions(platform);}
    @Test void absentInactiveZeroVersionAndMismatchedMembershipFailClosed(){member("padmin",false,1);assertEquals(401,assertThrows(DomainException.class,()->data(input().toString())).status);member("padmin",true,0);assertEquals(401,assertThrows(DomainException.class,()->data(input().toString())).status);when(platform.membership(ACTOR,TENANT)).thenReturn(Optional.of(new Membership(TENANT,TENANT,"padmin",1,true)));assertEquals(401,assertThrows(DomainException.class,()->data(input().toString())).status);when(platform.membership(ACTOR,TENANT)).thenReturn(Optional.empty());assertEquals(401,assertThrows(DomainException.class,()->data(input().toString())).status);var r=request(input().toString());r.setUserPrincipal(null);assertEquals(401,assertThrows(DomainException.class,()->controller.analyze(r)).status);}
    @Test void queriesUnknownFieldsAndWrongDecimalTypesRejected(){var r=request(input().toString());r.addParameter("tenant_id",TENANT);assertEquals(400,assertThrows(DomainException.class,()->controller.analyze(r)).status);for(var v:List.of(input().put("tenant_id",TENANT),input().put("publishable",true),input().put("trigger_hold_seconds",300),input().put("trigger_hold_seconds","1e3"))){assertEquals(400,assertThrows(DomainException.class,()->data(v.toString())).status);}var missing=input();missing.remove("recovery");assertEquals(400,assertThrows(DomainException.class,()->data(missing.toString())).status);}
    @Test void boundedStrictJsonRejectsDuplicateKeysTrailingAndDepth(){for(String value:List.of("{} {}","{\"direction\":null,\"direction\":null}",input().toString().replace("\"threshold\":\"70\"","\"threshold\":\"70\",\"threshold\":\"80\""),"[[[[1]]]]"," ".repeat(16385))){assertEquals(400,assertThrows(DomainException.class,()->data(value)).status);}}
}
